        const m = s.match(/(\d{1,2}):(\d{2}):(\d{2})(?:[.,](\d{1,3}))?/);
        if (!m) return null;
        const hh = Number(m[1]);
        const mm = Number(m[2]);
        const ss = Number(m[3]);
        const ms = Number((m[4] || "0").padEnd(3, "0"));
        if (![hh, mm, ss, ms].every(Number.isFinite)) return null;
        return ((hh * 60 + mm) * 60 + ss) * 1000 + ms;
