  const POINT_DETAILS_LAYOUT_KEY = "optimAnalyzer.pointDetails.layout";

  function readPointDetailsLayout() {
    try {
      const raw = localStorage.getItem(POINT_DETAILS_LAYOUT_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === "object" ? parsed : null;
    } catch (_e) {
      return null;
    }
  }

  function persistPointDetailsLayout(panel) {
    if (!panel) return;
    const rect = panel.getBoundingClientRect();
    const layout = {
      width: Math.round(rect.width || 0),
      height: Math.round(rect.height || 0),
      left: Math.round(rect.left || 0),
      top: Math.round(rect.top || 0),
      anchored: panel.dataset.userAnchored === "true",
      resized: panel.dataset.userResized === "true",
    };
    try {
      localStorage.setItem(POINT_DETAILS_LAYOUT_KEY, JSON.stringify(layout));
    } catch (_e) {}
  }

  function applySavedPointDetailsLayout(panel) {
    if (!panel) return false;
    const layout = readPointDetailsLayout();
    if (!layout) return false;
    if (Number.isFinite(Number(layout.width)) && Number(layout.width) >= 360) {
      panel.style.width = `${Math.min(window.innerWidth - 32, Number(layout.width))}px`;
    }
    if (
      Number.isFinite(Number(layout.height)) &&
      Number(layout.height) >= 320
    ) {
      panel.style.height = `${Math.min(window.innerHeight - 96, Number(layout.height))}px`;
    }
    if (
      layout.anchored &&
      Number.isFinite(Number(layout.left)) &&
      Number.isFinite(Number(layout.top))
    ) {
      const rect = panel.getBoundingClientRect();
      const maxLeft = Math.max(8, window.innerWidth - rect.width - 8);
      const maxTop = Math.max(8, window.innerHeight - rect.height - 8);
      panel.style.left = `${Math.min(maxLeft, Math.max(8, Number(layout.left)))}px`;
      panel.style.top = `${Math.min(maxTop, Math.max(8, Number(layout.top)))}px`;
      panel.style.right = "auto";
      panel.style.bottom = "auto";
      panel.dataset.userAnchored = "true";
    }
    if (layout.resized) panel.dataset.userResized = "true";
    return true;
  }

  function _getActualFloatingElement(el) {
    if (!el) return null;
    if (
      el.parentElement &&
      el.parentElement.classList.contains("window-content")
    ) {
      return el.parentElement.parentElement;
    }
    return el;
  }

  function getElementRectState(el) {
    el = _getActualFloatingElement(el);
    if (!el) return null;
    let left = el.offsetLeft, top = el.offsetTop, width = el.offsetWidth, height = el.offsetHeight;
    if (width === 0 && height === 0) {
      left = parseInt(el.style.left, 10) || 0;
      top = parseInt(el.style.top, 10) || 0;
      width = parseInt(el.style.width, 10) || 0;
      height = parseInt(el.style.height, 10) || 0;
    }
    return {
      left: Math.round(left),
      top: Math.round(top),
      width: Math.round(width),
      height: Math.round(height),
    };
  }

  function applyElementRectState(el, rect, options = {}) {
    el = _getActualFloatingElement(el);
    if (!el || !rect || typeof rect !== "object") return;
    const minLeft = Number.isFinite(Number(options.minLeft))
      ? Number(options.minLeft)
      : 8;
    const minTop = Number.isFinite(Number(options.minTop))
      ? Number(options.minTop)
      : 8;
    const maxWidth = Math.max(240, window.innerWidth - 24);
    const maxHeight = Math.max(180, window.innerHeight - 24);
    const width = Number(rect.width);
    const height = Number(rect.height);
    const left = Number(rect.left);
    const top = Number(rect.top);
    if (Number.isFinite(width) && width > 0)
      el.style.width = `${Math.min(maxWidth, width)}px`;
    if (Number.isFinite(height) && height > 0)
      el.style.height = `${Math.min(maxHeight, height)}px`;
    if (Number.isFinite(left) && Number.isFinite(top)) {
      const actualRect = el.getBoundingClientRect();
      const parentW = el.offsetParent ? el.offsetParent.clientWidth : window.innerWidth;
      const parentH = el.offsetParent ? el.offsetParent.clientHeight : window.innerHeight;
      const boundedLeft = Math.min(
        parentW - actualRect.width - 8,
        Math.max(minLeft, left),
      );
      const boundedTop = Math.min(
        parentH - actualRect.height - 8,
        Math.max(minTop, top),
      );
      el.style.left = `${boundedLeft}px`;
      el.style.top = `${boundedTop}px`;
      el.style.right = "auto";
      el.style.bottom = "auto";
      el.style.transform = "none";
    }
  }

