  function buildWorkspaceSnapshot() {
    const centerPane = document.getElementById("center-pane");
    const logsSidebar = document.getElementById("logs-sidebar");
    const pointPanel = document.getElementById("floatingInfoPanel");
    const failurePanel = document.getElementById("failureAnalysisPanel");
    const signalingModal = document.getElementById("signalingModal");
    const signalingContent = signalingModal
      ? signalingModal.querySelector(".modal-content")
      : null;
    const layersPanel = document.getElementById("smartcare-sidebar");
    const legendPanel = document.getElementById("draggable-legend");
    const activePointLog = window.__activePointLog || null;
    const activePoint = window.__currentPointDetailsPoint || null;
    const activePointIndex = activePointLog
      ? findPointIndexInLog(activePointLog, activePoint)
      : -1;
    const failureCtx = window.__currentFailureAnalysisContext || null;
    const failureLog = failureCtx
      ? loadedLogs.find((log) => String(log?.id) === String(failureCtx.logId))
      : null;
    const failurePointIndex =
      failureLog && failureCtx?.point
        ? findPointIndexInLog(failureLog, failureCtx.point)
        : -1;

    const isWinMinimized = (win) => {
      if (!win || !window.WM || !window.WM.dockContainer) return false;
      return Array.from(window.WM.dockContainer.children).some(item => item.__winRef === win);
    };

    return {
      version: 1,
      savedAt: new Date().toISOString(),
      layout: {
        pairedWorkspaceActive: !!(
          centerPane && centerPane.classList.contains("paired-workspace-grid")
        ),
        pairedCssVars: centerPane
          ? {
              leftWidth:
                centerPane.style.getPropertyValue("--paired-left-width") || "",
              bottomHeight:
                centerPane.style.getPropertyValue("--paired-bottom-height") ||
                "",
              pointHeight:
                centerPane.style.getPropertyValue("--paired-point-height") ||
                "",
            }
          : {},
        logsSidebarWidth: logsSidebar
          ? Math.round(logsSidebar.getBoundingClientRect().width || 0)
          : null,
        logsSidebarRect: logsSidebar ? getElementRectState(logsSidebar) : null,
        logsSidebarMinimized: logsSidebar && logsSidebar.closest(".floating-window") ? isWinMinimized(logsSidebar.closest(".floating-window")) : false,
        logsSidebarVisible: logsSidebar && logsSidebar.closest(".floating-window") ? (logsSidebar.closest(".floating-window").style.display !== "none" || isWinMinimized(logsSidebar.closest(".floating-window"))) : true,
        mapRect: document.getElementById("map") ? getElementRectState(document.getElementById("map")) : null,
        benchmarkRect: document.getElementById("benchmarkPanel") ? getElementRectState(document.getElementById("benchmarkPanel")) : null,
        benchmarkVisible: document.getElementById("benchmarkPanel") ? document.getElementById("benchmarkPanel").classList.contains("is-open") : false,
        losRect: document.getElementById("los-panel") ? getElementRectState(document.getElementById("los-panel")) : null,
        losVisible: document.getElementById("los-panel") ? document.getElementById("los-panel").classList.contains("los-panel--open") : false,
      },
      signaling: {
        visible: !!(
          window.isSignalingDocked ||
          (signalingModal && signalingModal.style.display !== "none") ||
          (signalingContent &&
            signalingContent.classList.contains("embedded-signaling-panel"))
        ),
        docked: !!window.isSignalingDocked,
        embedded: !!(
          signalingContent &&
          signalingContent.classList.contains("embedded-signaling-panel")
        ),
        logId: currentSignalingLogId || null,
        selectedSeq: Number.isFinite(
          Number(window.__currentSignalingSelection?.__signalingSeq),
        )
          ? Number(window.__currentSignalingSelection.__signalingSeq)
          : null,
        rect:
          signalingContent &&
          !(
            signalingContent.classList.contains("embedded-signaling-panel") ||
            window.isSignalingDocked
          )
            ? getElementRectState(signalingContent)
            : null,
        filter: document.getElementById("signalingFilter")?.value || "ALL",
        confidenceFilter:
          document.getElementById("signalingConfidenceFilter")?.value || "ALL",
        search: document.getElementById("signalingSearch")?.value || "",
      },
      pointDetails: {
        visible: !!(pointPanel && pointPanel.style.display !== "none"),
        rect: pointPanel ? getElementRectState(pointPanel) : null,
        logId: activePointLog?.id ?? null,
        pointIndex: activePointIndex,
      },
      layers: {
        visible: !!(layersPanel && layersPanel.style.display !== "none"),
        floating: !!(
          layersPanel && layersPanel.classList.contains("floating-layers-panel")
        ),
        rect: layersPanel ? getElementRectState(layersPanel) : null,
      },
      legend: {
        visible: !!legendPanel,
        rect: legendPanel ? getElementRectState(legendPanel) : null,
      },
      failureAnalysis: {
        visible: !!(failurePanel && failurePanel.style.display !== "none"),
        rect: failurePanel ? getElementRectState(failurePanel) : null,
        logId: failureCtx?.logId ?? null,
        pointIndex: failurePointIndex,
        mode: failureCtx?.mode || null,
      },
    };
  }

  function downloadWorkspaceSnapshot() {
    const snapshot = buildWorkspaceSnapshot();
    const blob = new Blob([JSON.stringify(snapshot, null, 2)], {
      type: "text/plain;charset=utf-8",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "workspace.txt";
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  function closeHeaderActionMenu() {
    const menu = document.getElementById("headerActionMenu");
    if (menu) menu.remove();
  }

  function triggerHiddenFilePicker(input, acceptValue = null) {
    if (!input) return;
    if (acceptValue) input.setAttribute("accept", acceptValue);
    input.value = "";
    const previousStyle = input.getAttribute("style") || "";
    input.style.position = "fixed";
    input.style.left = "-9999px";
    input.style.top = "0";
    input.style.width = "1px";
    input.style.height = "1px";
    input.style.opacity = "0";
    input.style.pointerEvents = "none";
    input.style.setProperty("display", "block", "important");
    try {
      if (typeof input.showPicker === "function") {
        input.showPicker();
      } else {
        input.click();
      }
    } catch (_err) {
      input.click();
    }
    setTimeout(() => {
      if (previousStyle) input.setAttribute("style", previousStyle);
      else input.removeAttribute("style");
    }, 0);
  }

  function openHeaderActionMenu(anchorBtn, items) {
    closeHeaderActionMenu();
    if (!anchorBtn) return;
    const safeItems = Array.isArray(items) ? items.filter(Boolean) : [];
    if (!safeItems.length) return;
    const rect = anchorBtn.getBoundingClientRect();
    const menu = document.createElement("div");
    menu.id = "headerActionMenu";
    menu.style.cssText = [
      "position:fixed",
      `top:${Math.round(rect.bottom + 8)}px`,
      `left:${Math.round(rect.left)}px`,
      "min-width:170px",
      "background:rgba(15,21,29,0.98)",
      "border:1px solid rgba(148,163,184,0.22)",
      "border-radius:10px",
      "box-shadow:0 12px 28px rgba(2,6,23,0.45)",
      "padding:6px",
      "z-index:130200",
    ].join(";");
    menu.innerHTML = safeItems
      .map(
        (item) =>
          '<button type="button" data-header-action="' +
          escapeHtml(String(item.id || "")) +
          '" style="width:100%; text-align:left; padding:9px 10px; background:transparent; border:none; color:#e2e8f0; border-radius:8px; cursor:pointer; font:inherit;">' +
          escapeHtml(String(item.label || item.id || "Action")) +
          "</button>",
      )
      .join("");
    document.body.appendChild(menu);
    menu.addEventListener("click", (event) => {
      const btn =
        event.target && event.target.closest
          ? event.target.closest("[data-header-action]")
          : null;
      if (!btn) return;
      const action = btn.getAttribute("data-header-action");
      closeHeaderActionMenu();
      const item = safeItems.find(
        (entry) => String(entry.id) === String(action),
      );
      if (item && typeof item.onClick === "function") {
        item.onClick();
      }
    });
    const onDocMouseDown = (event) => {
      if (menu.contains(event.target) || event.target === anchorBtn) return;
      closeHeaderActionMenu();
      document.removeEventListener("mousedown", onDocMouseDown);
    };
    setTimeout(() => document.addEventListener("mousedown", onDocMouseDown), 0);
  }

  function restoreWorkspaceSnapshot(snapshot) {
    if (!snapshot || typeof snapshot !== "object") return;
    const layout = snapshot.layout || {};
    const centerPane = document.getElementById("center-pane");
    const logsSidebar = document.getElementById("logs-sidebar");
    const signalingState = snapshot.signaling || {};
    const pointState = snapshot.pointDetails || {};
    const layersState = snapshot.layers || {};
    const legendState = snapshot.legend || {};
    const failureState = snapshot.failureAnalysis || {};

    if (layout.logsSidebarRect && logsSidebar) {
      applyElementRectState(logsSidebar, layout.logsSidebarRect, { minTop: 10 });
      // Restore minimized and visible state
      const win = logsSidebar.closest(".floating-window");
      if (win && window.WM) {
        // Handle visibility if explicitly saved
        if (layout.hasOwnProperty("logsSidebarVisible")) {
            if (layout.logsSidebarVisible === false) {
                win.style.display = "none";
            } else {
                const isMin = window.WM && window.WM.dockContainer && Array.from(window.WM.dockContainer.children).some(item => item.__winRef === win);
                if (layout.logsSidebarMinimized) {
                   if (!isMin) {
                       const minBtn = win.querySelector(".window-controls button[title='Minimize']");
                       if (minBtn) minBtn.click(); // Trigger minimize
                   }
                } else {
                   win.style.display = "flex";
                   if (isMin) {
                       // Find dock item and click it to restore
                       const dockItems = window.WM.dockContainer ? window.WM.dockContainer.querySelectorAll(".dock-item") : [];
                       for (let item of dockItems) {
                           if (item.__winRef === win) { item.click(); break; }
                       }
                   }
                }
            }
        }
      }
    } else if (logsSidebar && Number.isFinite(Number(layout.logsSidebarWidth))) {
      logsSidebar.style.width = `${Math.max(220, Math.min(520, Number(layout.logsSidebarWidth)))}px`;
    }
    const mapContainer = document.getElementById("map");
    if (layout.mapRect && mapContainer) {
      applyElementRectState(mapContainer, layout.mapRect, { minTop: 10 });
    }
    
    // Restore Benchmark visibility & position
    const benchmarkPanel = document.getElementById("benchmarkPanel");
    if (benchmarkPanel) {
      if (layout.benchmarkRect) applyElementRectState(benchmarkPanel, layout.benchmarkRect, { minTop: 10 });
      if (layout.hasOwnProperty("benchmarkVisible")) {
          if (typeof toggleBenchmarkPanel === "function") {
             toggleBenchmarkPanel(!!layout.benchmarkVisible, true);
          }
          const win = benchmarkPanel.closest(".floating-window");
          if (win) {
             win.style.display = layout.benchmarkVisible ? "flex" : "none";
          }
      }
    }

    // Restore LOS visibility & position
    const losPanel = document.getElementById("los-panel");
    if (losPanel) {
       if (layout.hasOwnProperty("losVisible")) {
           if (layout.losVisible && typeof window.losOpen === "function") {
              window.losOpen();
           } else if (!layout.losVisible && typeof window.losClose === "function") {
              window.losClose();
           }
       }
       // Apply rect AFTER window.losOpen() so its transform doesn't overwrite the loaded rect
       if (layout.losRect) applyElementRectState(losPanel, layout.losRect, { minTop: 10 });
    }

    if (
      centerPane &&
      layout.pairedCssVars &&
      typeof layout.pairedCssVars === "object"
    ) {
      if (layout.pairedCssVars.leftWidth)
        centerPane.style.setProperty(
          "--paired-left-width",
          String(layout.pairedCssVars.leftWidth),
        );
      if (layout.pairedCssVars.bottomHeight)
        centerPane.style.setProperty(
          "--paired-bottom-height",
          String(layout.pairedCssVars.bottomHeight),
        );
      if (layout.pairedCssVars.pointHeight)
        centerPane.style.setProperty(
          "--paired-point-height",
          String(layout.pairedCssVars.pointHeight),
        );
    }

    const signalingLog = loadedLogs.find(
      (log) =>
        String(log?.id) ===
        String(
          signalingState.logId || pointState.logId || failureState.logId || "",
        ),
    );
    if (
      layout.pairedWorkspaceActive &&
      signalingLog &&
      typeof applyPairedImportWorkspacePreset === "function"
    ) {
      applyPairedImportWorkspacePreset(signalingLog, null, {
        workspaceLayout: snapshot,
      });
    }

    if (layersState.visible) {
      if (typeof activateFloatingLayersPanel === "function") {
          activateFloatingLayersPanel();
      } else {
          const rightSidebar = document.getElementById("smartcare-sidebar");
          if (rightSidebar) {
             const win = rightSidebar.closest(".floating-window");
             if (win) win.style.display = "flex";
          }
      }
    } else {
      const rightSidebar = document.getElementById("smartcare-sidebar");
      if (rightSidebar) {
         const win = rightSidebar.closest(".floating-window");
         if (win) win.style.display = "none";
      }
    }
    if (layersState.rect) {
      setTimeout(() => {
        applyElementRectState(document.getElementById("smartcare-sidebar"), layersState.rect, { minTop: 60 });
      }, 120);
    }

    setTimeout(() => {
      if (
        signalingState.visible &&
        signalingLog &&
        typeof window.showSignalingModal === "function"
      ) {
        window.showSignalingModal(signalingLog.id);
        if (
          signalingState.docked &&
          !layout.pairedWorkspaceActive &&
          typeof window.dockSignaling === "function" &&
          !window.isSignalingDocked
        ) {
          window.dockSignaling();
        }
      }

      setTimeout(() => {
        const signalingContent = document.querySelector(
          "#signalingModal .modal-content",
        );
        const filterElement = document.getElementById("signalingFilter");
        const confidenceElement = document.getElementById(
          "signalingConfidenceFilter",
        );
        const searchElement = document.getElementById("signalingSearch");
        if (filterElement) filterElement.value = signalingState.filter || "ALL";
        if (confidenceElement)
          confidenceElement.value = signalingState.confidenceFilter || "ALL";
        if (searchElement) searchElement.value = signalingState.search || "";

        if (
          Number.isFinite(Number(pointState.pointIndex)) &&
          String(pointState.logId) &&
          typeof window.globalSync === "function"
        ) {
          const pointLog = loadedLogs.find(
            (log) => String(log?.id) === String(pointState.logId),
          );
          if (pointLog && pointLog.points?.[Number(pointState.pointIndex)]) {
            window.globalSync(
              pointLog.id,
              Number(pointState.pointIndex),
              "workspace-open",
            );
          }
        }

        if (
          signalingLog &&
          Number.isFinite(Number(signalingState.selectedSeq)) &&
          typeof window.jumpToSignalingMessageByMeta === "function"
        ) {
          window.jumpToSignalingMessageByMeta(
            signalingLog.id,
            Number(signalingState.selectedSeq),
          );
        } else if (
          typeof renderSignalingTable === "function" &&
          signalingLog &&
          signalingState.visible
        ) {
          renderSignalingTable();
        }

        if (
          signalingContent &&
          signalingState.rect &&
          !layout.pairedWorkspaceActive &&
          !window.isSignalingDocked
        ) {
          applyElementRectState(signalingContent, signalingState.rect, {
            minTop: 60,
          });
        }

        const pointPanel = document.getElementById("floatingInfoPanel");
        if (
          pointPanel &&
          pointState.visible &&
          pointState.rect &&
          !(
            centerPane && centerPane.classList.contains("paired-workspace-grid")
          )
        ) {
          applyElementRectState(pointPanel, pointState.rect, { minTop: 60 });
        }

        if (
          failureState.visible &&
          Number.isFinite(Number(failureState.pointIndex))
        ) {
          const failureLog = loadedLogs.find(
            (log) => String(log?.id) === String(failureState.logId),
          );
          const point =
            failureLog?.points?.[Number(failureState.pointIndex)] || null;
          const mode = point
            ? getSessionModeFromMapPoint(point)
            : failureState.mode;
          const session =
            point && failureLog
              ? findUmtsFailedSessionFromPoint(failureLog, point, mode) ||
                buildFallbackFailureSessionFromPoint(point, mode)
              : null;
          if (
            failureLog &&
            point &&
            session &&
            typeof window.openFailureAnalysisPanel === "function"
          ) {
            window.openFailureAnalysisPanel(failureLog, session, point);
            setTimeout(() => {
              const failurePanel = document.getElementById(
                "failureAnalysisPanel",
              );
              if (failurePanel && failureState.rect)
                applyElementRectState(failurePanel, failureState.rect, {
                  minTop: 60,
                });
            }, 80);
          }
        }

        if (legendState.visible) {
          if (
            !document.getElementById("draggable-legend") &&
            typeof window.updateLegend === "function"
          ) {
            window.updateLegend();
          }
          setTimeout(() => {
            const legendPanel = document.getElementById("draggable-legend");
            if (legendPanel && legendState.rect) {
              applyElementRectState(legendPanel, legendState.rect, {
                minTop: 60,
              });
            }
          }, 120);
        }
      }, 180);
    }, 120);
  }

