// ── Site search bar ───────────────────────────────────────────────────────────
(function () {
  const input = document.getElementById("siteSearchInput");
  const dropdown = document.getElementById("siteSearchDropdown");
  if (!input || !dropdown) return;

  function collectSiteNames(query) {
    if (!window.mapRenderer || !window.mapRenderer.siteLayers) return [];
    const q = query.trim().toLowerCase();
    const seen = new Set();
    const results = [];
    window.mapRenderer.siteLayers.forEach((layer) => {
      if (!layer.visible || !layer.sectors) return;
      for (const s of layer.sectors) {
        const name = String(s.siteName || s.name || "");
        if (!name || seen.has(name)) continue;
        if (!q || name.toLowerCase().includes(q)) {
          seen.add(name);
          results.push({ name, lat: s.lat, lng: s.lng });
          if (results.length >= 50) return;
        }
      }
    });
    return results.sort((a, b) => a.name.localeCompare(b.name));
  }

  function zoomToSite(lat, lng) {
    if (!window.mapRenderer) return;
    const map = window.mapRenderer.map;
    const maxZoom = map.getMaxZoom() || 19;
    map.setView([lat, lng], maxZoom, { animate: true });
  }

  function showDropdown(items) {
    dropdown.innerHTML = "";
    if (!items.length) {
      dropdown.style.display = "none";
      return;
    }
    items.forEach(({ name, lat, lng }) => {
      const div = document.createElement("div");
      div.className = "site-search-item";
      div.textContent = name;
      div.addEventListener("mousedown", (e) => {
        e.preventDefault();
        input.value = "";
        dropdown.style.display = "none";
        zoomToSite(lat, lng);
      });
      dropdown.appendChild(div);
    });
    dropdown.style.display = "block";
  }

  let debounce;
  input.addEventListener("input", () => {
    clearTimeout(debounce);
    const q = input.value.trim();
    if (!q) {
      dropdown.style.display = "none";
      return;
    }
    debounce = setTimeout(() => showDropdown(collectSiteNames(q)), 120);
  });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      const first = collectSiteNames(input.value)[0];
      if (first) {
        zoomToSite(first.lat, first.lng);
        input.value = "";
        dropdown.style.display = "none";
      }
    }
    if (e.key === "Escape") {
      input.value = "";
      dropdown.style.display = "none";
    }
  });

  input.addEventListener("focus", () => {
    if (input.value.trim()) showDropdown(collectSiteNames(input.value));
  });

  document.addEventListener("click", (e) => {
    if (!input.contains(e.target) && !dropdown.contains(e.target))
      dropdown.style.display = "none";
  });
})();
